-- Демо-данные для стенда: тестовые учётки всех ролей и компании из демо-сценария
-- с их представителями. Накатывается api при SEED_DEMO=true, повторный запуск
-- ничего не меняет. Всё синтетическое: ИНН с префиксом 0000 (код региона 00 ФНС
-- не выдаёт), ФИО и названия придуманы. Пароль у всех учёток demo12345.

-- стенд, поднятый до контактов, получает их на следующем старте
ON CONFLICT (login) DO UPDATE SET phone = excluded.phone, email = excluded.email;

-- Те же реквизиты отдаёт мок ЕГРЮЛ/ЕГРИП для этих ИНН, расходиться они не должны.
ON CONFLICT (inn) DO UPDATE SET okved_name = excluded.okved_name;

ON CONFLICT DO NOTHING;
